def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    stride = 5 if max(h, w) >= 19 else 4
    tile = 4

    # Find the full-height/full-width 3 band.
    stripe_rows = [r for r in range(h) if all(v == 3 for v in g[r])]
    stripe_cols = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    horizontal = bool(stripe_rows)
    if horizontal:
        band_index = stripe_rows[0] // stride
    else:
        band_index = stripe_cols[0] // stride

    starts_r = list(range(0, h, stride))
    starts_c = list(range(0, w, stride))
    # A repeated 4x4 motif is the content of every occupied tile.
    base = None
    for r in starts_r:
        for c in starts_c:
            if r + tile <= h and c + tile <= w and any(g[y][x] == 2 for y in range(r, r+tile) for x in range(c, c+tile)):
                base = [g[y][c:c+tile] for y in range(r, r+tile)]
                break
        if base is not None:
            break

    # The 3 band is a blank tile row/column. Fill each tile whose
    # corresponding motif-coordinate cell is occupied.
    if horizontal:
        tr = band_index
        r0 = tr * stride
        for tc, c0 in enumerate(starts_c):
            if tr < tile and tc < tile and base[tr][tc] == 2:
                for y in range(min(tile, h-r0)):
                    for x in range(min(tile, w-c0)):
                        g[r0+y][c0+x] = base[y][x]
    else:
        tc = band_index
        c0 = tc * stride
        for tr, r0 in enumerate(starts_r):
            if tr < tile and tc < tile and base[tr][tc] == 2:
                for y in range(min(tile, h-r0)):
                    for x in range(min(tile, w-c0)):
                        g[r0+y][c0+x] = base[y][x]

    # Remove the marker band, then mark the local pixel indexed by each tile's
    # position with 8.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                g[r][c] = 0
    for tr, r0 in enumerate(starts_r):
        for tc, c0 in enumerate(starts_c):
            if tr >= tile or tc >= tile or r0+tr >= h or c0+tc >= w:
                continue
            if any(g[y][x] == 2 for y in range(r0, min(r0+tile, h)) for x in range(c0, min(c0+tile, w))):
                if g[r0+tr][c0+tc] == 2:
                    g[r0+tr][c0+tc] = 8
    return g
